const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function wgs84ToRd(p){const f=.36*(p.lat-52.1551744),l=.36*(p.lng-5.38720621);const x=[[0,1,190094.945],[1,1,-11832.228],[2,1,-114.221],[0,3,-32.391],[1,0,-.705],[3,1,-2.34],[1,3,-.608],[0,2,-.008],[2,3,.148]];const y=[[1,0,309056.544],[0,2,3638.893],[2,0,73.077],[1,2,-157.984],[3,0,59.788],[0,1,.433],[2,2,-6.439],[1,1,-.032],[0,4,.092],[1,4,-.054]];return [155000+x.reduce((sum,[a,b,c])=>sum+c*f**a*l**b,0),463000+y.reduce((sum,[a,b,c])=>sum+c*f**a*l**b,0)];}
function officialPlanLink(id,p){const rd=p?.rd||'';const match=/POINT\(([-0-9.]+) ([-0-9.]+)\)/.exec(rd)||/([-0-9.]+),\s*([-0-9.]+)/.exec(rd);const xy=match?[match[1],match[2]]:p?wgs84ToRd(p).map(value=>value.toFixed(1)):null;const location=xy?`?locatie-stelsel=RD&locatie-x=${encodeURIComponent(xy[0])}&locatie-y=${encodeURIComponent(xy[1])}`:'';return `${OFFICIAL}documenten/${encodeURIComponent(id)}/plekinfo${location}`;}
function renderLayers(){let group='';const list=document.getElementById('layer-list');list.innerHTML=layerDefs.map(d=>{let heading='';if(d.group&&d.group!==group){group=d.group;heading=`<div class="layer-group-label">${group}</div>`;}return heading+`<label class="layer-row"><span class="layer-symbol">${icon(d.icon)}</span><span class="layer-label">${d.label}</span><input type="checkbox" data-layer="${d.id}" ${d.on?'checked':''}><span class="switch" aria-hidden="true"></span></label>`;}).join('');list.querySelectorAll('input').forEach(el=>el.addEventListener('change',()=>{const d=layerDefs.find(x=>x.id===el.dataset.layer);d.on=el.checked;updateLayers();if(d.on&&state.selected?.skippedLayers?.includes(d.id))loadOverlayForSelection(d,state.selected);}));updateLayerCount();}
function updateLayerCount(){document.getElementById('layer-count').textContent=`${layerDefs.filter(x=>x.on).length} active`;}
function renderLegend(){const selected=(state.selected?.primary?.properties?.bestemmingshoofdgroep||'').toLowerCase().trim(),matching=legendItems.find(item=>item[0]===selected);document.getElementById('legend-active').innerHTML=matching?`<span class="legend-color" style="background:${matching[2]}"></span><span><strong>Selected: ${esc(matching[1])}</strong><small>${esc(matching[0])} · PDOK category</small></span>`:'<span class="legend-active-empty">Select an area to match its official map category.</span>';document.getElementById('legend').innerHTML=legendItems.map(([dutch,english,color])=>`<div class="legend-item ${selected===dutch?'active':''}" title="${esc(dutch)} · ${esc(english)}"><span class="legend-color" style="background:${color}"></span><span>${esc(english)}<small>${esc(dutch)}</small></span></div>`).join('');renderSymbolLegends();}
function renderSymbolLegends(){const target=document.getElementById('symbol-legends');if(!target)return;const labels={double:'Dual designations',building:'Building envelopes',function:'Function designations',area:'Area designations',dimensions:'Dimensions'};target.innerHTML=layerDefs.filter(d=>d.on&&labels[d.id]).map(d=>`<figure><figcaption>${labels[d.id]}</figcaption><img loading="lazy" src="./legend/legend-${d.wms}.png" alt="PDOK ${labels[d.id]} symbols"></figure>`).join('')||'<p class="section-help">Turn on a plan layer to see its symbols.</p>';}

// Default 2D map: raster plan tiles over a street or BGT background.
function initMap(){
  const map=L.map('map',{zoomControl:false,preferCanvas:false,maxZoom:19,zoomSnap:.5,zoomDelta:.5,wheelPxPerZoomLevel:110,wheelDebounceTime:80,fadeAnimation:true,zoomAnimation:true,maxBounds:[[50.65,5.42],[51.88,6.37]],maxBoundsViscosity:.8}).fitBounds(REGION_BOUNDS,{padding:[24,24]});
  state.map=map;
  L.control.zoom({position:'bottomright'}).addTo(map);
  state.detailLayers.selection=L.layerGroup().addTo(map);
  state.detailLayers.pin=L.layerGroup().addTo(map);
  state.base={
    osm:L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}),
    bgt:L.tileLayer(BGT_BASE,{attribution:'© PDOK / Kadaster BGT',minZoom:15,maxZoom:19}),
    aerial:L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles © Esri',maxZoom:19})
  };
  for(const d of layerDefs)state.planLayers[d.id]=L.tileLayer.wms(d.cad?CAD_WMS:PLAN_WMS,{layers:d.wms,format:'image/png',transparent:true,version:'1.3.0',opacity:d.id==='parcels'?.85:1,maxZoom:19,updateWhenZooming:false,updateWhenIdle:true,updateInterval:200,keepBuffer:2,attribution:d.cad?'© PDOK / Kadaster':'© PDOK Ruimtelijke plannen'});
  updateBase();updateLayers();updateViewLabel();
  map.on('zoomend',()=>{updateBase();updateViewLabel();updateLayers();});
  map.on('click',e=>selectPoint(e.latlng));
  map.on('mousemove',e=>document.getElementById('coordinates').textContent=`${e.latlng.lat.toFixed(5)}° N, ${e.latlng.lng.toFixed(5)}° E`);
  setTimeout(()=>map.invalidateSize(),50);
}
function updateViewLabel(){const map=state.perspective&&state.perspectiveReady?state.perspectiveMap:state.map;document.getElementById('view-label').textContent=map.getZoom()>=15?'Detailed plankaart':state.municipality==='all'?'Limburg plan overview':'Municipality plan overview';}
function polygonContains(ring,p){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p.lat)!==(b[1]>p.lat)&&p.lng<(b[0]-a[0])*(p.lat-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
function geometryContains(geometry,p){const polygons=geometry.type==='Polygon'?[geometry.coordinates]:geometry.coordinates;return polygons.some(rings=>polygonContains(rings[0],p)&&!rings.slice(1).some(hole=>polygonContains(hole,p)));}
function municipalityAt(p){return state.region?.municipalities.find(m=>p.lat>=m.bounds[0]&&p.lat<=m.bounds[2]&&p.lng>=m.bounds[1]&&p.lng<=m.bounds[3]&&geometryContains(m.geometry,p));}
function inLimburg(p){return state.region?geometryContains(state.region.province.geometry,p):true;}
function boundsOf(b){return [[b[0],b[1]],[b[2],b[3]]];}
function updateBoundaryVisibility(){if(!state.region)return;const overview=state.map.getZoom()<13;if(state.municipalityLayer){if(overview&&!state.map.hasLayer(state.municipalityLayer))state.municipalityLayer.addTo(state.map);if(!overview&&state.map.hasLayer(state.municipalityLayer))state.map.removeLayer(state.municipalityLayer);}state.municipalityLayer?.bringToFront();state.boundaryLayer?.bringToFront();state.detailLayers.selection.bringToFront?.();state.detailLayers.pin.bringToFront?.();}
async function loadRegion(){
  const response=await fetch('./limburg.json');if(!response.ok)throw new Error('Limburg boundary unavailable');state.region=await response.json();
  const selector=document.getElementById('municipality');selector.innerHTML='<option value="all">All Limburg · 31 municipalities</option>'+state.region.municipalities.map(m=>`<option value="${esc(m.code)}">${esc(m.name)}</option>`).join('');
  selector.value=state.municipality;
  state.municipalityLayer=L.geoJSON({type:'FeatureCollection',features:state.region.municipalities.map(m=>({type:'Feature',geometry:m.geometry,properties:{name:m.name}}))},{style:{color:'#9eead6',weight:1,opacity:.5,fillOpacity:0},interactive:false});
  state.boundaryLayer=L.geoJSON({type:'Feature',geometry:state.region.province.geometry},{style:{color:'#42e4b3',weight:2.5,opacity:.95,fillOpacity:0,dashArray:'6 5'},interactive:false}).addTo(state.map);
  updateBoundaryVisibility();
  navigateToBounds(state.region.province.bounds);updatePerspectiveRegion();
}
function selectMunicipality(code){
  const m=state.region?.municipalities.find(item=>item.code===code);
  state.municipality=m?m.code:'all';document.getElementById('municipality').value=state.municipality;
  navigateToBounds(m?m.bounds:state.region?.province.bounds||[...REGION_BOUNDS[0],...REGION_BOUNDS[1]]);
  updateViewLabel();
}
function renderWelcome(){document.getElementById('detail-content').innerHTML=`<div class="empty-detail"><span class="empty-symbol">${icon('map')}</span><h2>Explore the Limburg plankaart</h2><p>Choose any of the 31 municipalities, search an address or parcel, or click a plan area. Zoom in for building footprints, parcel lines and the exact planning geometry.</p><button class="source-link" type="button" id="example-button">Explore Maagdendries example ${icon('arrow-right')}</button></div>`;document.getElementById('example-button').onclick=()=>{selectMunicipality('0935');navigateToPoint(FOCUS,17);selectPoint(FOCUS);};}
function loadSaved(){try{const data=JSON.parse(localStorage.getItem('planview-saved-v1')||'[]');state.saved=Array.isArray(data)?data.filter(item=>Number.isFinite(item.lat)&&Number.isFinite(item.lng)).slice(0,30):[];}catch{state.saved=[];}renderSaved();}
function persistSaved(){try{localStorage.setItem('planview-saved-v1',JSON.stringify(state.saved));}catch{showToast('This browser could not save the area.');}}
function samePoint(a,b){return Math.abs(a.lat-b.lat)<.00001&&Math.abs(a.lng-b.lng)<.00001;}
function renderSaved(){const list=document.getElementById('saved-areas');document.getElementById('saved-count').textContent=`${state.saved.length} area${state.saved.length===1?'':'s'}`;list.innerHTML=state.saved.length?state.saved.map(item=>`<div class="saved-area"><button type="button" class="saved-area-main" data-saved="${esc(item.id)}"><strong>${esc(item.label)}</strong><span>${esc(item.designation||'Planning location')} · ${esc(item.municipality||'Limburg')}</span></button><button type="button" class="saved-area-remove" data-remove="${esc(item.id)}" aria-label="Remove ${esc(item.label)}">${icon('x')}</button></div>`).join(''):'<p class="saved-empty">Select a plan area to save it for later review.</p>';list.querySelectorAll('[data-saved]').forEach(button=>button.onclick=()=>{const item=state.saved.find(x=>x.id===button.dataset.saved);if(!item)return;navigateToPoint(item,17);selectPoint({lat:item.lat,lng:item.lng,address:item.label,rd:item.rd});document.getElementById('sidebar').classList.remove('open');});list.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{state.saved=state.saved.filter(x=>x.id!==button.dataset.remove);persistSaved();renderSaved();if(state.selected)renderDetails();});}
function saveCurrent(){const selected=state.selected;if(!selected)return;const p=selected.point;if(state.saved.some(item=>samePoint(item,p))){showToast('This area is already saved.');return;}const record=(selected.layers.documents||[]).find(item=>item.identificatie===selected.primary?.properties?.plangebied);state.saved.unshift({id:crypto.randomUUID(),lat:p.lat,lng:p.lng,rd:p.rd||'',label:pointLabel(p),designation:selected.primary?.properties?.naam||'No designation polygon',municipality:selected.municipality?.name||'',plan:record?.naam||''});state.saved=state.saved.slice(0,30);persistSaved();renderSaved();renderDetails();showToast('Area saved on this device.');}
function buildCaseBrief(){const selected=state.selected;if(!selected)return '';const p=selected.point,pr=selected.primary?.properties||{},record=(selected.layers.documents||[]).find(item=>item.identificatie===pr.plangebied),pp=selected.parcel?.properties||{};const parcel=pp.perceelnummer?`${pp.AKRKadastraleGemeenteCodeWaarde||''} ${pp.sectie||''} ${pp.perceelnummer}`.trim():'Not returned';const names=([['Dual designations',selected.layers.double],['Function designations',selected.layers.function],['Area designations',selected.layers.area],['Building envelopes',selected.layers.building],['Dimensions',selected.layers.dimensions]]).map(([label,items])=>`${label}: ${[...new Set(featuresAtPoint(items||[],p).filter(item=>item.properties?.plangebied===pr.plangebied).map(item=>item.properties?.naam).filter(Boolean))].join('; ')||'None returned'}`);const rule=pr.verwijzingnaartekst?.split(',')[0]||'Not supplied';return ['PLANVIEW · SPATIAL PLAN RESEARCH BRIEF',`Prepared: ${new Date().toLocaleString('en-GB')}`,...(selected.loadingLayers?['Note: secondary plan overlay queries were still loading when this brief was copied.']:[]),...(selected.skippedLayers?.length?[`Not queried because layer was off: ${selected.skippedLayers.join(', ')}`]:[]),`Location: ${pointLabel(p)}`,`Municipality: ${selected.municipality?.name||'Check source'}`,`Coordinates: ${p.lat.toFixed(6)} N, ${p.lng.toFixed(6)} E`,`Cadastral parcel at point: ${parcel}`,'',`Designation: ${pr.naam||'No designation polygon returned'}`,`Plan: ${record?.naam||planTitle(pr.plangebied||'')}`,`Document type: ${record?.typeplan||pr.typeplan||'Check source'}`,`Legal status in PDOK: ${record?.dossierstatus||pr.planstatus||'Check source'}`,`Plan date: ${record?.datum||pr.datum||'Check source'}`,`IMRO ID: ${pr.plangebied||'No designation source ID returned'}`,...names,'',`Designation rule: ${rule}`,`Official document at this point: ${pr.plangebied?officialPlanLink(pr.plangebied,p):OFFICIAL}`,`Omgevingsloket legal check: ${OFFICIAL}`,'',`Source method: PDOK GetFeatureInfo designation polygon and plan-area document metadata; parcel from PDOK Kadastrale Kaart.`,`Research aid only. Check current Omgevingsplan, supplementary rules and legal effect in Omgevingsloket.`].join('\n');}
async function copyCaseBrief(){try{await navigator.clipboard.writeText(buildCaseBrief());showToast('Research brief copied.');}catch{showToast('Clipboard unavailable in this browser.');}}
function wireCaseActions(){document.getElementById('save-area')?.addEventListener('click',saveCurrent);document.getElementById('copy-brief')?.addEventListener('click',copyCaseBrief);}
function showToast(message){const toast=document.getElementById('app-toast');toast.textContent=message;toast.hidden=false;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.hidden=true,3500);}
function navigateToPoint(p,zoom=17){state.map.flyTo([p.lat,p.lng],zoom,{duration:.65});state.perspectiveMap?.flyTo({center:[p.lng,p.lat],zoom,duration:650});}
function navigateToBounds(bounds){state.map.fitBounds(boundsOf(bounds),{padding:[30,30],animate:true});state.perspectiveMap?.fitBounds([[bounds[1],bounds[0]],[bounds[3],bounds[2]]],{padding:30,duration:650});}
function mapOpacity(d,zoom){if(state.mapStyle==='official')return 1;return d.id==='zoning'?(zoom>=12?.72:.46):d.id==='building'?.55:d.id==='parcels'?.62:.28;}
function perspectiveStyle(){
  const sources={osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'},bgt:{type:'raster',tiles:[BGT_BASE],tileSize:256,attribution:'© PDOK / Kadaster BGT'},aerial:{type:'raster',tiles:['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,attribution:'Tiles © Esri'},region:{type:'geojson',data:{type:'FeatureCollection',features:[]}},selection:{type:'geojson',data:{type:'FeatureCollection',features:[]}}};
  const layers=[{id:'base-osm',type:'raster',source:'osm'},{id:'base-bgt',type:'raster',source:'bgt',layout:{visibility:'none'}},{id:'base-aerial',type:'raster',source:'aerial',layout:{visibility:'none'}}];
  for(const d of layerDefs){const endpoint=d.cad?CAD_WMS:PLAN_WMS;sources[`source-${d.id}`]={type:'raster',tiles:[`${endpoint}?service=WMS&request=GetMap&version=1.3.0&layers=${encodeURIComponent(d.wms)}&styles=&format=image/png&transparent=true&crs=EPSG:3857&bbox={bbox-epsg-3857}&width=256&height=256`],tileSize:256,attribution:d.cad?'© PDOK / Kadaster':'© PDOK Ruimtelijke plannen'};layers.push({id:`plan-${d.id}`,type:'raster',source:`source-${d.id}`,layout:{visibility:d.on?'visible':'none'},paint:{'raster-opacity':mapOpacity(d,16),'raster-fade-duration':120}});}
  layers.push({id:'municipality-lines',type:'line',source:'region',filter:['==',['get','kind'],'municipality'],paint:{'line-color':'#9eead6','line-width':1,'line-opacity':.55}},{id:'province-line',type:'line',source:'region',filter:['==',['get','kind'],'province'],paint:{'line-color':'#42e4b3','line-width':2.5,'line-dasharray':[3,2]}},{id:'selected-fill',type:'fill',source:'selection',filter:['==',['get','kind'],'designation'],paint:{'fill-color':'#72e4c5','fill-opacity':.2}},{id:'selected-outline',type:'line',source:'selection',filter:['==',['get','kind'],'designation'],paint:{'line-color':'#082d3b','line-width':4}},{id:'parcel-outline',type:'line',source:'selection',filter:['==',['get','kind'],'parcel'],paint:{'line-color':'#fff','line-width':2.5,'line-dasharray':[2,2]}},{id:'selected-pin',type:'circle',source:'selection',filter:['==',['get','kind'],'pin'],paint:{'circle-radius':7,'circle-color':'#74e8c3','circle-stroke-color':'#0e2833','circle-stroke-width':3}});
  return {version:8,sources,layers};
}
// Tilted visualization of the same 2D legal plan data; no height model is invented.
async function initPerspective(){
  const module=await import('./vendor/maplibre-gl.mjs');
  const center=state.map.getCenter();
  const map=new module.Map({container:'perspective-map',style:perspectiveStyle(),center:[center.lng,center.lat],zoom:state.map.getZoom(),pitch:56,bearing:-18,maxBounds:[[5.42,50.65],[6.37,51.88]],maxPitch:70,canvasContextAttributes:{antialias:true}});
  state.perspectiveMap=map;
  map.addControl(new module.NavigationControl({showCompass:true,visualizePitch:true}),'bottom-right');
  map.on('click',event=>selectPoint({lat:event.lngLat.lat,lng:event.lngLat.lng}));
  map.on('mousemove',event=>document.getElementById('coordinates').textContent=`${event.lngLat.lat.toFixed(5)}° N, ${event.lngLat.lng.toFixed(5)}° E`);
  map.on('zoomend',()=>{updatePerspectiveLayers();updateViewLabel();});
  await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Perspective map style timed out')),20000);map.once('style.load',()=>{clearTimeout(timer);resolve();});});
  state.perspectiveReady=true;updatePerspectiveRegion();updatePerspectiveSelection();updatePerspectiveLayers();map.resize();
}
function updatePerspectiveRegion(){if(!state.perspectiveReady||!state.region)return;const features=state.region.municipalities.map(m=>({type:'Feature',geometry:m.geometry,properties:{kind:'municipality',name:m.name}}));features.push({type:'Feature',geometry:state.region.province.geometry,properties:{kind:'province'}});state.perspectiveMap.getSource('region').setData({type:'FeatureCollection',features});}
function updatePerspectiveSelection(){if(!state.perspectiveReady)return;const selected=state.selected,p=selected?.point;const features=[];if(selected?.primary?.geometry){const f=geoToLatLng(selected.primary);f.properties={...f.properties,kind:'designation'};features.push(f);}if(selected?.parcel?.geometry){const f=geoToLatLng(selected.parcel);f.properties={...f.properties,kind:'parcel'};features.push(f);}if(p)features.push({type:'Feature',geometry:{type:'Point',coordinates:[p.lng,p.lat]},properties:{kind:'pin'}});state.perspectiveMap.getSource('selection').setData({type:'FeatureCollection',features});}
function updatePerspectiveLayers(){if(!state.perspectiveReady)return;const map=state.perspectiveMap,zoom=map.getZoom(),detailed=zoom>=12,base=state.aerial?'aerial':zoom>=15?'bgt':'osm';for(const name of ['osm','bgt','aerial'])map.setLayoutProperty(`base-${name}`,'visibility',name===base?'visible':'none');for(const d of layerDefs){map.setLayoutProperty(`plan-${d.id}`,'visibility',d.on&&(d.id==='zoning'||detailed)?'visible':'none');map.setPaintProperty(`plan-${d.id}`,'raster-opacity',mapOpacity(d,zoom));}map.setLayoutProperty('municipality-lines','visibility',zoom<13?'visible':'none');if(state.perspective){document.getElementById('area-count').textContent=detailed?'PDOK plan layers':'Zoom for fine layers';document.getElementById('basemap-name').textContent=state.aerial?'Aerial':zoom>=15?'BGT detail':'Map';}}
async function togglePerspective(){const button=document.getElementById('perspective-toggle'),label=document.getElementById('perspective-label'),container=document.getElementById('perspective-map');if(state.perspective){state.perspective=false;const center=state.perspectiveMap.getCenter();state.map.setView([center.lat,center.lng],state.perspectiveMap.getZoom(),{animate:false});container.hidden=true;button.setAttribute('aria-pressed','false');label.textContent='Perspective';state.map.invalidateSize();updateBase();updateLayers();updateViewLabel();return;}button.disabled=true;label.textContent='Loading…';container.hidden=false;try{if(!state.perspectiveMap)await initPerspective();else{const center=state.map.getCenter();state.perspectiveMap.jumpTo({center:[center.lng,center.lat],zoom:state.map.getZoom(),pitch:56,bearing:-18});state.perspectiveMap.resize();}state.perspective=true;button.setAttribute('aria-pressed','true');label.textContent='Top-down';updatePerspectiveLayers();updateViewLabel();showToast('Perspective tilts the published 2D plan map; heights are not represented.');}catch(error){container.hidden=true;label.textContent='Perspective';showToast('Perspective view is unavailable here.');console.error(error);}finally{button.disabled=false;}}
function updateBase(){const map=state.map;if(!map)return;const chosen=state.aerial?state.base.aerial:map.getZoom()>=15?state.base.bgt:state.base.osm;for(const base of Object.values(state.base))if(map.hasLayer(base)&&base!==chosen)map.removeLayer(base);if(!map.hasLayer(chosen))chosen.addTo(map);chosen.bringToBack();document.getElementById('basemap-name').textContent=state.aerial?'Aerial':map.getZoom()>=15?'BGT detail':'Map';updatePerspectiveLayers();}
function updateLayers(){const map=state.map;updateLayerCount();renderSymbolLegends();if(!map)return;const detailed=map.getZoom()>=12;for(const d of layerDefs){const layer=state.planLayers[d.id],visible=d.on&&(d.id==='zoning'||detailed);if(visible&&!map.hasLayer(layer))layer.addTo(map);if(!visible&&map.hasLayer(layer))map.removeLayer(layer);layer.setOpacity(mapOpacity(d,map.getZoom()));}updateBoundaryVisibility();document.getElementById('area-count').textContent=detailed?'PDOK plan layers':'Zoom for fine layers';updatePerspectiveLayers();}
function mercator(p){const r=6378137;return [r*p.lng*Math.PI/180,r*Math.log(Math.tan(Math.PI/4+p.lat*Math.PI/360))];}
function featureUrl(endpoint,layer,p,format='application/json; subtype=geojson',count=30){const [x,y]=mercator(p);const half=95;const params=new URLSearchParams({service:'WMS',version:'1.3.0',request:'GetFeatureInfo',layers:layer,query_layers:layer,CRS:'EPSG:3857',bbox:`${x-half},${y-half},${x+half},${y+half}`,width:'512',height:'512',i:'256',j:'256',feature_count:String(count),info_format:format});return `${endpoint}?${params}`;}
function parseCollections(raw){const all=[];let start=-1,depth=0,inString=false,slash=false;for(let i=0;i<raw.length;i++){const c=raw[i];if(start<0){if(c==='{'){start=i;depth=1;}continue;}if(inString){if(slash)slash=false;else if(c==='\\')slash=true;else if(c==='"')inString=false;continue;}if(c==='"'){inString=true;continue;}if(c==='{')depth++;else if(c==='}'){depth--;if(depth===0){try{const data=JSON.parse(raw.slice(start,i+1));if(Array.isArray(data.features))all.push(...data.features);}catch{}start=-1;}}}return all;}
// A point query asks PDOK which official geometries and documents intersect the click.
async function fetchFeatures(endpoint,layer,p){const res=await fetch(featureUrl(endpoint,layer,p));if(!res.ok)throw new Error(`PDOK ${res.status}`);return parseCollections(await res.text());}
async function fetchPlanRecords(p){const res=await fetch(featureUrl(PLAN_WMS,'plangebied',p,'text/plain',100));if(!res.ok)throw new Error(`PDOK ${res.status}`);const raw=await res.text();return raw.split(/\n  Feature \d+:\s*\n/).slice(1).map(block=>{const record={};for(const line of block.split('\n')){const m=/^    ([a-zA-Z0-9_]+) = '(.*)'$/.exec(line);if(m)record[m[1]]=m[2];}return record;}).filter(x=>x.identificatie);}
function pointLabel(p){return p.address||`${p.lat.toFixed(5)}° N, ${p.lng.toFixed(5)}° E`;}
function planTitle(id){if(id==='NL.IMRO.0935.bpNutsbedrijven-oh01')return 'Nutsbedrijven';if(id==='NL.IMRO.0935.bpMtrichtNoordwest-vg01')return 'Maastricht Noordwest';const tail=(id||'').split('.').pop().replace(/-(vg|oh|ow|va|vs)\d+$/i,'').replace(/^bp/i,'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/([A-Za-z])([0-9])/g,'$1 $2');return tail||'Local spatial plan';}
function choosePrimary(features,p){return [...featuresAtPoint(features,p)].sort((a,b)=>{const score=p=>(p.historisch==='0'?100:0)+(p.planstatus==='onherroepelijk'?30:p.planstatus==='vastgesteld'?20:0)+(p.typeplan==='bestemmingsplan'?10:0)+(p.plangebied?5:0);return score(b.properties||{})-score(a.properties||{});})[0];}
function geoToLatLng(feature){if(!feature?.geometry)return null;const unproject=coords=>{const p=L.CRS.EPSG3857.unproject(L.point(coords[0],coords[1]));return [p.lng,p.lat];};const geometry=feature.geometry;const mapCoords=c=>typeof c[0]==='number'?unproject(c):c.map(mapCoords);return {type:'Feature',properties:feature.properties||{},geometry:{type:geometry.type,coordinates:mapCoords(geometry.coordinates)}};}
function featuresAtPoint(features,p){const exact=features.filter(feature=>{const geo=geoToLatLng(feature);return geo&&['Polygon','MultiPolygon'].includes(geo.geometry.type)&&geometryContains(geo.geometry,p);});return exact.length?exact:features;}
function drawSelection(primary,parcel,p){const group=state.detailLayers.selection;group.clearLayers();if(primary?.geometry){const geo=geoToLatLng(primary);if(geo)L.geoJSON(geo,{style:{color:'#082d3b',weight:4,fillColor:'#72e4c5',fillOpacity:.12,opacity:.95}}).addTo(group);}if(parcel?.geometry){const geo=geoToLatLng(parcel);if(geo)L.geoJSON(geo,{style:{color:'#fff',weight:2.5,dashArray:'5 5',fillOpacity:0}}).addTo(group);}const pin=state.detailLayers.pin;pin.clearLayers();L.circleMarker([p.lat,p.lng],{radius:7,color:'#0e2833',weight:3,fillColor:'#74e8c3',fillOpacity:1}).addTo(pin);updatePerspectiveSelection();}
async function selectPoint(p){
  const ticket=++state.request;
  if(!inLimburg(p)){
    document.getElementById('detail-content').innerHTML=`<div class="empty-detail"><span class="empty-symbol">${icon('map')}</span><h2>Outside Limburg</h2><p>Choose a location inside the province boundary.</p></div>`;
    return;
  }
  const municipality=municipalityAt(p);
  if(municipality){state.municipality=municipality.code;document.getElementById('municipality').value=municipality.code;updateViewLabel();}
  state.selectedPoint=p;
  document.getElementById('detail-content').innerHTML=`<div class="empty-detail"><span class="empty-symbol">${icon('compass')}</span><h2>Reading official plan…</h2><p>Finding the designation and its source.</p></div>`;
  // Resolve the clicked designation, its plan record and parcel before optional rule overlays.
  const coreRequests=[['zoning',PLAN_WMS,'enkelbestemming'],['parcel',CAD_WMS,'Perceelvlak']];
  const coreResults=await Promise.allSettled([
    ...coreRequests.map(async([key,url,layer])=>[key,await fetchFeatures(url,layer,p)]),
    fetchPlanRecords(p).then(records=>['documents',records])
  ]);
  if(ticket!==state.request)return;
  const layers={};
  for(const result of coreResults)if(result.status==='fulfilled')layers[result.value[0]]=result.value[1];
  const primary=choosePrimary(layers.zoning||[],p);
  const parcel=featuresAtPoint(layers.parcel||[],p)[0];
  const overlayIds=['double','building','function','area','dimensions'];
  const overlayDefs=layerDefs.filter(d=>overlayIds.includes(d.id));
  const activeOverlays=overlayDefs.filter(d=>d.on);
  const skippedLayers=overlayDefs.filter(d=>!d.on).map(d=>d.id);
  const selected={point:p,primary,parcel,layers,municipality,failed:coreResults.filter(result=>result.status==='rejected').length,loadingLayers:true,pendingLayers:activeOverlays.map(d=>d.id),skippedLayers};
  state.selected=selected;
  drawSelection(primary,parcel,p);
  renderDetails();renderLegend();
  document.getElementById('detail-panel').scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
  if(window.innerWidth<=900)document.getElementById('detail-panel').classList.add('open');
  // Load enabled secondary rule layers after the primary source is already visible.
  const overlayResults=await Promise.allSettled(activeOverlays.map(async d=>[d.id,await fetchFeatures(PLAN_WMS,d.wms,p)]));
  if(ticket!==state.request||state.selected!==selected)return;
  for(const result of overlayResults){if(result.status==='fulfilled')selected.layers[result.value[0]]=result.value[1];else selected.failed++;}
  const completedIds=new Set(activeOverlays.map(d=>d.id));
  selected.pendingLayers=selected.pendingLayers.filter(id=>!completedIds.has(id));
  selected.skippedLayers=overlayDefs.filter(d=>!d.on&&!selected.layers[d.id]).map(d=>d.id);
  selected.loadingLayers=selected.pendingLayers.length>0;
  const scrollTop=document.getElementById('detail-panel').scrollTop;
  renderDetails();document.getElementById('detail-panel').scrollTop=scrollTop;
}

async function loadOverlayForSelection(layer,selected){
  if(!selected||selected.layers[layer.id]||selected.pendingLayers.includes(layer.id))return;
  selected.pendingLayers.push(layer.id);selected.loadingLayers=true;
  const ticket=state.request;renderDetails();
  try{selected.layers[layer.id]=await fetchFeatures(PLAN_WMS,layer.wms,selected.point);}catch{selected.failed++;}
  if(ticket!==state.request||state.selected!==selected)return;
  selected.pendingLayers=selected.pendingLayers.filter(id=>id!==layer.id);
  selected.skippedLayers=layerDefs.filter(d=>['double','building','function','area','dimensions'].includes(d.id)&&!d.on&&!selected.layers[d.id]).map(d=>d.id);
  selected.loadingLayers=selected.pendingLayers.length>0;
  const scrollTop=document.getElementById('detail-panel').scrollTop;
  renderDetails();document.getElementById('detail-panel').scrollTop=scrollTop;
}

function valueRow(label,value){return `<div class="metric"><div class="metric-label">${esc(label)}</div><div class="metric-value">${esc(value||'—')}</div></div>`;}
function uniqueFeatures(arr){const seen=new Set();return (arr||[]).filter(f=>{const k=`${f.properties?.plangebied}|${f.properties?.naam}`;if(seen.has(k))return false;seen.add(k);return true;});}
// The detail panel presents the geometry-linked plan first and other documents separately.
function renderDetails(){const s=state.selected;if(!s)return;const p=s.point,pr=s.primary?.properties||{},sourceId=pr.plangebied||'',planRecord=(s.layers.documents||[]).find(d=>d.identificatie===sourceId),title=planRecord?.naam||planTitle(sourceId),pp=s.parcel?.properties||{},parcelName=pp.perceelnummer?`${pp.AKRKadastraleGemeenteCodeWaarde||''} ${pp.sectie||''} ${pp.perceelnummer}`.trim():'No parcel returned';const status=planRecord?.dossierstatus||pr.dossierstatus||pr.planstatus||'Check official source';const sourceDate=planRecord?.datum||pr.datum;const date=sourceDate?new Date(`${sourceDate}T00:00:00`).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Check official source';const url=sourceId?officialPlanLink(sourceId,p):OFFICIAL;const parcelMatch=/\(([A-Z0-9]+)\)\s+([A-Z])\s+(\d+)/.exec(p.name||'');const searchedParcel=parcelMatch?`${parcelMatch[1]} ${parcelMatch[2]} ${parcelMatch[3]}`:null;const parcelConflict=searchedParcel&&parcelName!==searchedParcel;const txt=pr.verwijzingnaartekst?.split(',')[0];const d=featuresAtPoint(s.layers.double||[],p).filter(f=>f.properties?.plangebied===sourceId);const f=featuresAtPoint(s.layers.function||[],p).filter(f=>f.properties?.plangebied===sourceId);const a=featuresAtPoint(s.layers.area||[],p).filter(f=>f.properties?.plangebied===sourceId);const m=featuresAtPoint(s.layers.dimensions||[],p).filter(f=>f.properties?.plangebied===sourceId);const b=featuresAtPoint(s.layers.building||[],p).filter(f=>f.properties?.plangebied===sourceId);const ruleParts=[['Dual designations',d],['Function designations',f],['Area designations',a],['Dimensions',m],['Building envelopes',b]].filter(([,v])=>v.length);const overlayNames={double:'Dual designations',building:'Building envelopes',function:'Function designations',area:'Area designations',dimensions:'Dimensions'};const featureStatus=s.loadingLayers?'<p class="secondary-intro">Loading additional plan rules…</p>':'';const skippedNote=s.skippedLayers?.length?`<p class="secondary-intro">Not queried while switched off: ${s.skippedLayers.map(id=>overlayNames[id]).join(', ')}. Turn that layer on to include it.</p>`:'';const requestWarning=s.failed?'<p class="source-warning">Some map details could not be loaded. Verify the complete rules in the official portal.</p>':'';const featureRows=ruleParts.map(([label,arr])=>`<div class="official-feature-group"><div class="official-feature-label">${label} <span>${arr.length}</span></div>${uniqueFeatures(arr).slice(0,4).map(x=>`<div class="official-feature-row"><span>${esc(x.properties?.naam||label)}</span>${x.properties?.verwijzingnaartekst?`<a href="${esc(x.properties.verwijzingnaartekst.split(',')[0])}" target="_blank" rel="noopener noreferrer" aria-label="Open official rule">${icon('external')}</a>`:''}</div>`).join('')}</div>`).join('');const authority=planRecord?.naamoverheid||s.municipality?.name||'';const otherDocs=(s.layers.documents||[]).filter(d=>d.identificatie!==sourceId&&(!authority||d.naamoverheid?.replace(/^gemeente /i,'')===authority.replace(/^gemeente /i,'')));const facetDocs=otherDocs.filter(d=>/facet|parkeer|short stay/i.test(d.naam||'')).slice(0,4);const hiddenCount=otherDocs.length-facetDocs.length;const facetHtml=facetDocs.map(d=>`<div class="secondary-item"><div><strong>${esc(d.naam)}</strong><span>${esc(d.typeplan||'Plan')} · possible supplementary rule · ${esc(d.planstatus||'status to verify')}</span></div><a href="${esc(officialPlanLink(d.identificatie,p))}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(d.naam)}">${icon('external')}</a></div>`).join('');const target=document.getElementById('detail-content');if(!s.primary){const localDocs=(s.layers.documents||[]).filter(doc=>(doc.gemeentecode===s.municipality?.code||doc.identificatie?.startsWith(`NL.IMRO.${s.municipality?.code}.`))&&/bestemmingsplan|beheersverordening|inpassingsplan|uitwerkingsplan|wijzigingsplan/i.test(doc.typeplan||'')).sort((a,b)=>(b.historisch==='0')-(a.historisch==='0')).slice(0,4);const links=localDocs.map(doc=>`<div class="secondary-item"><div><strong>${esc(doc.naam)}</strong><span>${esc(doc.typeplan)} · ${esc(doc.planstatus||'status to verify')} · ${esc(doc.identificatie)}</span></div><a href="${esc(officialPlanLink(doc.identificatie,p))}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(doc.naam)}">${icon('external')}</a></div>`).join('');target.innerHTML=`<div class="empty-detail"><span class="empty-symbol">${icon('map')}</span><h2>No designation polygon here</h2><p>PDOK returned no zoning designation at this point${s.failed?' or some layers could not be loaded':''}. ${localDocs.length?'These local document footprints intersect the point, but their rules still need checking in the official portal.':'Check the Omgevingsloket for the current legal rules.'}</p>${links?`<div style="margin-top:18px">${links}</div>`:''}<p style="margin-top:18px"><a class="source-link" href="${OFFICIAL}" target="_blank" rel="noopener noreferrer">Open Omgevingsloket ${icon('external')}</a></p><div class="detail-actions"><button type="button" class="detail-action" id="save-area">${icon('map-pin')} Save area</button><button type="button" class="detail-action" id="copy-brief">${icon('file')} Copy case brief</button></div></div>`;wireCaseActions();return;}target.innerHTML=`<div class="detail-inner"><div class="detail-top"><div class="detail-overline"><span>OFFICIAL PLAN FEATURE</span><button id="close-details" title="Close details" aria-label="Close details">${icon('x')}</button></div><div class="detail-title-row"><div class="area-symbol" style="background:#72e4c5">${icon('map')}</div><div><h2>${esc(pr.naam||'Designation')}</h2><div class="detail-location">${esc(pointLabel(p))}</div></div></div><div class="tag-row"><span class="tag tag-primary">${esc(pr.bestemmingshoofdgroep||'ZONING').toUpperCase()}</span><span class="tag tag-outline">PDOK PLAN MAP</span></div><div class="detail-actions"><button type="button" class="detail-action ${state.saved.some(item=>samePoint(item,p))?'saved':''}" id="save-area">${icon('map-pin')} ${state.saved.some(item=>samePoint(item,p))?'Saved':'Save area'}</button><button type="button" class="detail-action" id="copy-brief">${icon('file')} Copy case brief</button></div><p class="case-note">For planning research · saved locations stay in this browser.</p></div><section class="detail-section"><h3>What intersects this point</h3><div class="metric-grid">${valueRow('Primary designation',pr.naam)}${valueRow('Cadastral parcel',parcelName)}${valueRow('Municipality',s.municipality?.name||planRecord?.naamoverheid)}${valueRow('Plan status',pr.planstatus)}${valueRow('Plan date',date)}</div>${parcelConflict?`<p class="source-warning">The search index names ${esc(searchedParcel)}, while the current cadastral map returns ${esc(parcelName)} at this point. Confirm the parcel boundary in the official cadastre.</p>`:''}</section><section class="detail-section"><h3>Primary applicable source</h3><div class="source-card"><div class="source-eyebrow">${icon('check')} GEOMETRY + DOCUMENT MATCH</div><h4>${esc(title)}</h4><div class="source-sub">${esc(planRecord?.typeplan||pr.typeplan||'Spatial plan')} · ${esc(planRecord?.naamoverheid||s.municipality?.name||'Municipality to verify')}</div><dl class="source-facts"><div><dt>Legal status</dt><dd>${esc(status)}</dd></div><div><dt>Plan date</dt><dd>${esc(date)}</dd></div><div style="grid-column:1/-1"><dt>IMRO document ID</dt><dd>${esc(sourceId)}</dd></div></dl><a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open in Omgevingsloket ${icon('external')}</a></div><button type="button" class="why-button" id="why-button" aria-expanded="false">Why this source? ${icon('chevron-down')}</button><div id="why-content" class="why-content" hidden><p>The PDOK designation geometry at this exact point carries document ID <strong>${esc(sourceId)}</strong>. That direct feature-to-document link determines the primary zoning source shown here.</p><p>Other instruments and supplementary rules may also apply. Use the Omgevingsloket link for the complete current legal position.</p></div></section><section class="detail-section"><h3>Plan features at this point</h3><p class="secondary-intro">These shapes and labels come from the published spatial-plan map. Select a rule link to read its original text.</p><div class="official-feature-group"><div class="official-feature-label">Designation</div><div class="official-feature-row"><span>${esc(pr.naam)}</span>${txt?`<a href="${esc(txt)}" target="_blank" rel="noopener noreferrer" aria-label="Open zoning rule">${icon('external')}</a>`:''}</div></div>${featureRows||(!s.loadingLayers?'<p class="secondary-intro">No additional plan features returned at this point.</p>':'')}${featureStatus}${skippedNote}${requestWarning}</section><section class="detail-section"><h3>Geometry and provenance</h3><div class="provenance-row"><strong>Designation polygon</strong><span>PDOK Ruimtelijke plannen · ${esc(pr.identificatie||'feature')} · ${esc(sourceId)}</span></div><div class="provenance-row"><strong>Parcel outline</strong><span>PDOK Kadastrale Kaart · ${esc(parcelName)}${pp.identificatieLokaalID?' · '+esc(pp.identificatieLokaalID):''}</span></div><div class="provenance-row"><strong>Buildings and streets</strong><span>PDOK BGT detailed background</span></div></section><section class="detail-section"><h3>Other documents</h3><p class="secondary-intro">Potentially supplementary documents are separated from the plan that supplies this designation.</p>${facetHtml}${hiddenCount>0?`<div class="secondary-item"><div><strong>${hiddenCount} other municipality document${hiddenCount===1?'':'s'} de-emphasized</strong><span>No direct source link to this designation. Review legal effect in the official portal.</span></div></div>`:''}<a class="source-link" href="${OFFICIAL}" target="_blank" rel="noopener noreferrer">Check all rules at this location ${icon('external')}</a></section></div>`;document.getElementById('why-button').onclick=()=>{const el=document.getElementById('why-content');el.hidden=!el.hidden;document.getElementById('why-button').setAttribute('aria-expanded',String(!el.hidden));};document.getElementById('close-details').onclick=()=>document.getElementById('detail-panel').classList.remove('open');wireCaseActions();}
function parseWkt(s){const m=/POINT\(([-0-9.]+) ([-0-9.]+)\)/.exec(s||'');return m?{lng:Number(m[1]),lat:Number(m[2])}:null;}
// Search returns a location; source ranking still happens only after the point query.
async function searchOfficial(q){
  const parcelQuery=/\b[A-Z]{2,4}\d{2}\b/i.test(q)||/\b[A-Z]\s*\d{3,6}\b/i.test(q);
  const params=new URLSearchParams({q,rows:'12',fq:parcelQuery?'type:perceel':'provincienaam:Limburg'});
  const response=await fetch(`https://api.pdok.nl/bzk/locatieserver/search/v3_1/free?${params}`);
  if(!response.ok)throw new Error('Location search unavailable');
  const data=await response.json();
  return (data.response?.docs||[]).map(d=>({...parseWkt(d.centroide_ll),name:d.weergavenaam,type:d.type,municipality:d.gemeentenaam,rd:d.centroide_rd})).filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng)&&inLimburg(x)).slice(0,8);
}
function initSearch(){const input=document.getElementById('search'),box=document.getElementById('search-results');let timer=0,ticket=0;input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(q.length<3){box.hidden=true;return;}timer=setTimeout(async()=>{const n=++ticket;box.hidden=false;box.innerHTML='<div style="padding:12px;color:var(--muted);font-size:12px">Searching official address records…</div>';try{const found=await searchOfficial(q);if(n!==ticket)return;state.searchResults=found;box.innerHTML=found.length?found.map((x,i)=>`<button type="button" class="search-result" data-result="${i}"><strong>${esc(x.name)}</strong><small>PDOK location · ${esc(x.type)} · ${esc(x.municipality||"Limburg")}</small></button>`).join(''):'<div style="padding:12px;color:var(--muted);font-size:12px">No Limburg result found.</div>';box.querySelectorAll('[data-result]').forEach(el=>el.onclick=()=>chooseSearch(Number(el.dataset.result)));}catch{box.innerHTML='<div style="padding:12px;color:var(--muted);font-size:12px">Search unavailable. You can click the map.</div>';}},280);});input.addEventListener('keydown',e=>{if(e.key==='Enter'){const first=box.querySelector('[data-result]');if(first)chooseSearch(Number(first.dataset.result));}if(e.key==='Escape')box.hidden=true;});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))box.hidden=true;});}
function chooseSearch(index){const p=state.searchResults[index];if(!p)return;document.getElementById('search').value=p.name;document.getElementById('search-results').hidden=true;const m=municipalityAt(p);if(m){state.municipality=m.code;document.getElementById('municipality').value=m.code;}navigateToPoint(p,17);selectPoint({...p,address:p.name});}
function wireControls(){
  document.getElementById('theme-toggle').onclick=()=>{const light=document.body.classList.toggle('theme-light');document.body.classList.toggle('theme-dark',!light);document.getElementById('theme-toggle').innerHTML=icon(light?'sun':'moon');};
  document.getElementById('fit-city').onclick=()=>selectMunicipality('all');
  document.getElementById('municipality').onchange=e=>selectMunicipality(e.target.value);
  document.getElementById('basemap-toggle').onclick=()=>{state.aerial=!state.aerial;updateBase();};
  document.getElementById('render-toggle').onclick=()=>{state.mapStyle=state.mapStyle==='clean'?'official':'clean';document.getElementById('render-mode-label').textContent=state.mapStyle==='clean'?'Clean view':'Official ink';document.getElementById('render-toggle').setAttribute('aria-pressed',String(state.mapStyle==='official'));updateLayers();showToast(state.mapStyle==='official'?'Full PDOK layer opacity.':'Reduced overlay opacity for a clearer view.');};
  document.getElementById('perspective-toggle').onclick=togglePerspective;
  document.getElementById('reset-filters').onclick=()=>{for(const d of layerDefs)d.on=['zoning','double','building','function','area','parcels'].includes(d.id);document.querySelectorAll('[data-layer]').forEach(el=>el.checked=layerDefs.find(d=>d.id===el.dataset.layer).on);updateLayers();};
  document.getElementById('mobile-layers').onclick=()=>document.getElementById('sidebar').classList.add('open');
  document.getElementById('close-layers').onclick=()=>document.getElementById('sidebar').classList.remove('open');
  document.getElementById('mobile-details').onclick=()=>document.getElementById('detail-panel').classList.add('open');
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('search').focus();}if(e.key==='Escape'){document.getElementById('sidebar').classList.remove('open');document.getElementById('detail-panel').classList.remove('open');document.getElementById('search-results').hidden=true;}});
}
function init(){loadSaved();renderLayers();renderLegend();initMap();wireControls();initSearch();renderWelcome();loadRegion().catch(()=>{document.getElementById('municipality').innerHTML='<option value="all">Limburg</option>';});}
window.addEventListener('load',init);
